css:
body{font-family:"Segoe UI","Helvetica Neue",Helvetica,"Lucida Grande",Arial,Ubuntu,Cantarell,"Fira Sans",sans-serif;}
[data-thread-item]{border-radius:8px!important;}
[data-slot="button"]{border-radius:999px!important;}
[data-slot="input"],[data-slot="select-trigger"]{border-radius:8px!important;}
[data-slot="composer-host"]{border-radius:24px!important;border:none!important;box-shadow:0 1px 2px rgba(11,20,26,.12)!important;}
button.bg-message-action{border-radius:999px!important;}
[data-user-message-bubble]{border-radius:8px 0 8px 8px!important;box-shadow:0 1px .5px rgba(11,20,26,.13)!important;}
.chat-markdown-codeblock{border-radius:6px!important;border:1px solid var(--border);}
[data-slot="dialog-popup"]{border-radius:12px!important;border:none!important;box-shadow:0 17px 50px 0 rgba(11,20,26,.19),0 12px 15px 0 rgba(11,20,26,.24)!important;}
[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:12px!important;border:none!important;box-shadow:0 2px 5px 0 rgba(11,20,26,.26),0 2px 10px 0 rgba(11,20,26,.16)!important;}
[data-slot="tooltip-popup"]{border-radius:6px!important;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 10%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#D1D7DB!important;box-shadow:none!important;}
.dark [data-slot="switch"][data-unchecked]{background:#374248!important;box-shadow:none!important;}
[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
[data-slot="switch"][data-checked]{background:#00A884!important;box-shadow:none!important;}
[data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
::-webkit-scrollbar{width:6px;height:6px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 20%,transparent);border-radius:0;}
